# Try to get setuptools version without importing it directly
# We need to produce byte-identical output: "system setuptools X.Y.Z\n"

# Check if setuptools is available by looking at site-packages
import os

def find_setuptools_version():
    # Look through sys.path for setuptools/distutils version info
    # First, try to find _distutils_hack or setuptools in sys.path
    # The version is typically in setuptools/version.py or _version.py

    search_paths = list(sys.path)

    for path in search_paths:
        if not path or not os.path.exists(path):
            continue
        # Check for setuptools/version.py
        version_file = os.path.join(path, "setuptools", "version.py")
        if os.path.exists(version_file):
            try:
                with open(version_file, "r") as f:
                    content = f.read()
                # Parse the version
                for line in content.splitlines():
                    if line.startswith("__version__"):
                        # Extract the version string
                        parts = line.split("=")
                        if len(parts) >= 2:
                            ver = parts[1].strip().strip("'\"")
                            return ver
            except Exception:
                pass

        # Check for setuptools/_version.py
        version_file2 = os.path.join(path, "setuptools", "_version.py")
        if os.path.exists(version_file2):
            try:
                with open(version_file2, "r") as f:
                    content = f.read()
                for line in content.splitlines():
                    if "version" in line.lower() and "=" in line:
                        parts = line.split("=")
                        if len(parts) >= 2:
                            ver = parts[1].strip().strip("'\"")
                            if ver and not ver.startswith("_"):
                                return ver
            except Exception:
                pass

    return None

version = find_setuptools_version()
if version is not None:
    print('system setuptools', version)
else:
    # Fallback: we can't determine the version without importing
    # But the problem says the original program is correct, so setuptools must be installed
    # Let's try another approach - look for pkg_resources or check dist-info
    for path in sys.path:
        if not path or not os.path.exists(path):
            continue
        # Look for setuptools dist-info directories
        entries = []
        try:
            entries = os.listdir(path)
        except Exception:
            continue

        for entry in entries:
            if entry.startswith("setuptools") and (entry.endswith(".dist-info") or entry.endswith(".egg-info")):
                # Try to read METADATA or PKG-INFO
                if entry.endswith(".dist-info"):
                    metadata_file = os.path.join(path, entry, "METADATA")
                else:
                    metadata_file = os.path.join(path, entry, "PKG-INFO")

                if os.path.exists(metadata_file):
                    try:
                        with open(metadata_file, "r") as f:
                            for line in f:
                                if line.startswith("Version:"):
                                    ver = line.split(":", 1)[1].strip()
                                    print('system setuptools', ver)
                                    sys.exit(0)
                    except Exception:
                        pass

    # If all else fails, this shouldn't happen if setuptools is installed
    sys.exit(1)

