def isqrt(n):
    if n < 0:
        raise ValueError("isqrt() argument must be non-negative")
    if n == 0:
        return 0
    # Initial guess using bit length
    x = 1 << ((n.bit_length() + 1) // 2)
    while True:
        y = (x + n // x) // 2
        if y >= x:
            break
        x = y
    # Ensure we have the floor of the square root
    while x * x > n:
        x -= 1
    return x

