def shorten(text, width=40, placeholder='…', **kwargs):
    if len(text) <= width:
        return text
    if len(placeholder) >= width:
        return placeholder[:width]

    words = text.split()
    current = ''
    for word in words:
        candidate = word if not current else current + ' ' + word
        if len(candidate) + len(placeholder) <= width:
            current = candidate
        else:
            break

    return current + placeholder

