def shorten(text, width):
    if len(text) <= width:
        return text
    words = text.split()
    current = []
    current_len = 0
    for word in words:
        if not current:
            current.append(word)
            current_len = len(word)
        else:
            new_len = current_len + 1 + len(word)
            if new_len <= width - 1:  # leave room for ellipsis
                current.append(word)
                current_len = new_len
            else:
                break
    return ' '.join(current) + '…'

