def shorten(s, width=80, placeholder="..."):
    if len(s) <= width:
        return s
    cutoff = width - len(placeholder)
    if cutoff <= 0:
        return placeholder
    # Try to cut at a word boundary
    truncated = s[:cutoff]
    last_space = truncated.rfind(' ')
    if last_space != -1:
        truncated = truncated[:last_space].rstrip()
    return truncated + placeholder

