import os

# Get all standard library module names without using sys.stdlib_module_names
# We'll use importlib to find them by scanning the standard library paths

def get_stdlib_modules():
    modules = set()

    # Get the standard library paths
    stdlib_paths = []
    for path in sys.path:
        # Check if this is a standard library path (not site-packages or user paths)
        real_path = os.path.realpath(path)
        # Standard library paths typically contain 'lib/python' or similar
        if 'python' in real_path.lower() or 'Lib' in path or 'lib' in path.lower():
            stdlib_paths.append(real_path)

    # Also add the known standard library location
    # Try to find it via os
    prefix = getattr(sys, 'prefix', '')
    if prefix:
        possible_paths = [
            os.path.join(prefix, 'lib'),
            os.path.join(prefix, 'Lib'),
        ]
        for p in possible_paths:
            if os.path.exists(p):
                stdlib_paths.append(p)

    # Deduplicate while preserving order isn't needed since we use a set
    seen_paths = set()
    unique_paths = []
    for p in stdlib_paths:
        if p not in seen_paths:
            seen_paths.add(p)
            unique_paths.append(p)

    # Scan each path for .py files and directories
    for base_path in unique_paths:
        if not os.path.isdir(base_path):
            continue
        try:
            entries = os.listdir(base_path)
        except (OSError, PermissionError):
            continue

        for entry in entries:
            full_path = os.path.join(base_path, entry)
            # Check for .py files
            if entry.endswith('.py'):
                module_name = entry[:-3]  # Remove .py
                if not module_name.startswith('_'):
                    modules.add(module_name)
            elif os.path.isdir(full_path):
                # Check if it's a package (has __init__.py)
                init_file = os.path.join(full_path, '__init__.py')
                if os.path.isfile(init_file):
                    if not entry.startswith('_'):
                        modules.add(entry)

    # Also need to include built-in modules and frozen modules
    # Built-in modules
    try:
        builtin_names = sys.builtin_module_names
        for name in builtin_names:
            if not name.startswith('_'):
                modules.add(name)
    except AttributeError:
        pass

    return modules


