    for p in sys.path:
        if not p.startswith('.'):
            paths.append(p)

    modules = set()

    for path in paths:
        if not os.path.isdir(path):
            continue

        try:
            entries = os.listdir(path)
        except (OSError, PermissionError):
            continue

        for entry in entries:
            full_path = os.path.join(path, entry)

            # Check if it's a .py file
            if entry.endswith('.py') and not entry.startswith('_') and not entry.startswith('.'):
                name = entry[:-3]  # Remove .py
                # Skip test files, __init__, etc.
                if name == '__main__' or name == '__future__':
                    pass
                # Skip files that are part of packages (check if there's a directory)
                if os.path.isdir(full_path):
                    continue
                # Make sure it's a valid module name
                if name.isidentifier() or all(c.isalnum() or c == '_' for c in name):
                    modules.add(name)

            # Check if it's a package directory with __init__.py
            elif os.path.isdir(full_path) and not entry.startswith('_') and not entry.startswith('.'):
                init_file = os.path.join(full_path, '__init__.py')
                if os.path.isfile(init_file):
                    if entry.isidentifier() or all(c.isalnum() or c == '_' for c in entry):
