def textwrap_dedent(s):
    if not s:
        return s
    # Find the minimum indentation among all non-empty lines
    lines = s.split('\n')
    # For dedent, we consider trailing newlines as well
    # The standard behavior: strip the common leading whitespace from all lines
    # Lines that are blank (empty or all whitespace) are ignored for the purpose of finding min indent

    indents = []
    for line in lines:
        if line.strip() == '':
            continue
        # Find the length of leading whitespace
        i = 0
        while i < len(line) and line[i] in (' ', '\t'):
            i += 1
        indents.append(i)

    if not indents:
        return s

    min_indent = min(indents)

    result_lines = []
    for line in lines:
        if line.strip() == '':
            result_lines.append(line)
        else:
            # Remove min_indent characters from the start
            # But only if they are all whitespace
            if min_indent > 0:
                # Check that the first min_indent chars are whitespace
                prefix = line[:min_indent]
                if all(c in (' ', '\t') for c in prefix):
                    result_lines.append(line[min_indent:])
                else:
                    result_lines.append(line)
            else:
                result_lines.append(line)

    return '\n'.join(result_lines)


