    for line in lines:
        if line.strip():
            indent = len(line) - len(line.lstrip())
            indents.append(indent)

    if not indents:
        return text

    min_indent = min(indents)

    if min_indent == 0:
        return text

    # Remove the common indent from each line
    result_lines = []
    for line in lines:
        if line.strip():
            result_lines.append(line[min_indent:])
        else:
            result_lines.append(line)

    return '\n'.join(result_lines)


