def textwrap_fill(s, width):
    words = s.split()
    if not words:
        return ""
    lines = []
    current_line = []
    current_length = 0
    for word in words:
        if current_line:
            if current_length + 1 + len(word) <= width:
                current_line.append(word)
                current_length += 1 + len(word)
            else:
                lines.append(" ".join(current_line))
                current_line = [word]
                current_length = len(word)
        else:
            current_line = [word]
            current_length = len(word)
    if current_line:
        lines.append(" ".join(current_line))
    return "\n".join(lines)


def textwrap_dedent(text):
    lines = text.split('\n')
    # Find minimum indentation of non-empty lines
    margins = []
    for line in lines:
        stripped = line.lstrip(' ')
        if stripped:
            indent = len(line) - len(stripped)
            margins.append(indent)
    if not margins:
        return text
    margin = min(margins)
    if margin == 0:
        return text
    result_lines = []
    for line in lines:
        if line.startswith(' ' * margin):
            result_lines.append(line[margin:])
        else:
            result_lines.append(line)
    return '\n'.join(result_lines)


