def dedent(text):
    lines = text.split('\n')
    # Find the minimum indentation of non-empty lines
    indentations = []
    for line in lines:
        if line.strip():
            indent = len(line) - len(line.lstrip())
            indentations.append(indent)
    if not indentations:
        return text
    common_indent = min(indentations)
    if common_indent == 0:
        return text
    new_lines = []
    for line in lines:
        if line.strip():
            new_lines.append(line[common_indent:])
        else:
            new_lines.append(line)
    return '\n'.join(new_lines)

