            if i < len(before_dot):
                width_str = before_dot[i:]
                if width_str:
                    width = int(width_str)

            v = int(value)
            if conv == 'x':
                result = format(v, 'x')
            else:
                result = format(v, 'X')

            if precision is not None and precision > 0:
                result = result.zfill(precision)

            if width is not None and width > len(result):
                if '-' in flags:
                    result = result.ljust(width)
                elif '0' in flags:
                    result = result.zfill(width)
                else:
                    result = result.rjust(width)

            return result
        else:
            return _simple_percent(fmt, value)
    elif conv == 'o':
        # Octal
        if '.' in rest:
            parts = rest.split('.')
            before_dot = parts[0]
            after_dot = parts[1] if len(parts) > 1 else ''
            precision = int(after_dot) if after_dot else None

            flags = ''
            width = None
            i = 0
            while i < len(before_dot) and before_dot[i] in '+- 0#':
                flags += before_dot[i]
                i += 1
            if i < len(before_dot):
                width_str = before_dot[i:]
                if width_str:
                    width = int(width_str)

            v = int(value)
            result = format(v, 'o')

            if precision is not None and precision > 0:
                result = result.zfill(precision)

            if width is not None and width > len(result):
                if '-' in flags:
                    result = result.ljust(width)
                elif '0' in flags:
                    result = result.zfill(width)
                else:
                    result = result.rjust(width)

            return result
        else:
            return _simple_percent(fmt, value)
    elif conv == 'c':
        # Character
        v = int(value)
        return chr(v)
    elif conv == 's':
        # String
        if '.' in rest:
            parts = rest.split('.')
            before_dot = parts[0]
            after_dot = parts[1] if len(parts) > 1 else ''
            precision = int(after_dot) if after_dot else None

            flags = ''
            width = None
            i = 0
            while i < len(before_dot) and before_dot[i] in '+- 0#':
                flags += before_dot[i]
                i += 1
            if i < len(before_dot):
                width_str = before_dot[i:]
                if width_str:
                    width = int(width_str)

            v = str(value)

            if precision is not None:
                v = v[:precision]

            if width is not None and width > len(v):
                if '-' in flags:
                    v = v.ljust(width)
                elif '0' in flags:
                    v = v.zfill(width)
                else:
                    v = v.rjust(width)

            return v
        else:
            return _simple_percent(fmt, value)
    else:
        return _simple_percent(fmt, value)


def _simple_percent(fmt, value):
    """Fallback for simple percent formats without problematic constructs."""
    return fmt % value


for s in ['%.2d','%.2i','%.2u','%.2x','%.2X','%.2o','%.2c','%.2s','%.0d','%.d','%5.2d','%-5.2d','%05.2d','%+.2d','%05.7d']:
    v = 'a' if s.endswith('s') else (65 if s.endswith('c') else -1)
    try: r = repr(_percent_format(s, v))
    except Exception as e: r = '%s: %s' % (type(e).__name__, str(e)[:40])
    print('  %-8s %% %-4r -> %s' % (s, v, r))

def safe_format(s, v):
    try:
        return repr(s % v)
    except Exception as e:
        return '%s: %s' % (type(e).__name__, str(e)[:40])

