import json, tempfile, datetime, pathlib, os

def _recent_capture_note(path):
    try:
        with open(path, 'r') as f:
            lines = f.readlines()
    except (FileNotFoundError, OSError):
        return None

    now = datetime.datetime.now(datetime.timezone.utc)
    cutoff = now - datetime.timedelta(days=7)

    most_recent = None
    for line in lines:
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except json.JSONDecodeError:
            continue
        ts_str = obj.get("ts")
        if not ts_str:
            continue
        try:
            # Parse the timestamp
            ts = datetime.datetime.strptime(ts_str, "%Y-%m-%dT%H:%M:%S.%fZ").replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            continue
        if ts >= cutoff:
            detail = obj.get("detail", "")
            if most_recent is None or ts > most_recent[0]:
                most_recent = (ts, detail)

    if most_recent is None:
        return None
    return most_recent[1]

