import json, tempfile, datetime, pathlib, os

def _recent_capture_note(path):
    try:
        with open(path, 'r') as f:
            lines = f.readlines()
    except (FileNotFoundError, OSError):
        return None

    now = datetime.datetime.now(datetime.timezone.utc)
    cutoff = now - datetime.timedelta(days=7)

    for line in reversed(lines):
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except json.JSONDecodeError:
            continue
        if obj.get("kind") != "note":
            continue
        ts = obj.get("ts")
        if not ts:
            continue
        try:
            ts_dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except (ValueError, AttributeError):
            continue
        if ts_dt >= cutoff:
            return obj.get("detail")
    return None

