import json, os


def walk_dir(top):
    """Recursively walk directory, yielding (root, dirs, files) like os.walk."""
    try:
        entries = os.listdir(top)
    except OSError:
        return
    dirs = []
    files = []
    for name in entries:
        path = top + '/' + name
        try:
            if os.path.isdir(path):
                dirs.append(name)
            else:
                files.append(name)
        except OSError:
            pass
    yield top, dirs, files
    for d in dirs:
        yield from walk_dir(top + '/' + d)


