def repr_str(s):
    """Return a repr-like string for s, handling non-ASCII chars as \\uXXXX etc."""
    # If the string is all printable ASCII (33-126) and non-empty, use single quotes
    # But we need to match Python's repr behavior exactly for the cases that matter.

    # Let's build it character by character
    result = []
    for c in s:
        code = ord(c)
        if code == 39:  # single quote
            result.append("'")
        elif code == 92:  # backslash
            result.append('\\')
        elif 32 <= code <= 126:
            result.append(c)
        else:
            if code < 128:
                # Control chars
                if code == 9:
                    result.append('\\t')
                elif code == 10:
                    result.append('\\n')
                elif code == 13:
                    result.append('\\r')
                else:
                    result.append('\\x%02x' % code)
            else:
                # Non-ASCII
                if code < 0x10000:
                    result.append('\\u%04x' % code)
                else:
                    # Surrogate pair
                    v = code - 0x10000
                    hi = 0xD800 + (v >> 10)
                    lo = 0xDC00 + (v & 0x3FF)
                    result.append('\\u%04x\\u%04x' % (hi, lo))

    # Now decide quoting: Python uses double quotes if the string contains single quotes but no double quotes,
    # and single quotes otherwise. But for our purposes, let's check what Python does.
    # Actually, Python's repr uses single quotes by default, unless the string contains a single quote
    # and doesn't contain a double quote, in which case it uses double quotes.

    has_single = "'" in s
    has_double = '"' in s

    if has_single and not has_double:
        quote_char = '"'
        # Rebuild with double-quote awareness: inside double quotes, " needs escaping
        result2 = []
        for c in s:
            code = ord(c)
            if code == 34:  # double quote
                result2.append('\\"')
            elif code == 39:  # single quote - no escape needed inside double quotes
                result2.append("'")
            elif code == 92:  # backslash
                result2.append('\\')
            elif 32 <= code <= 126:
                result2.append(c)
            else:
                if code < 128:
                    if code == 9:
                        result2.append('\\t')
                    elif code == 10:
                        result2.append('\\n')
                    elif code == 13:
                        result2.append('\\r')
                    else:
                        result2.append('\\x%02x' % code)
                else:
                    if code < 0x10000:
                        result2.append('\\u%04x' % code)
                    else:
                        v = code - 0x10000
                        hi = 0xD800 + (v >> 10)
                        lo = 0xDC00 + (v & 0x3FF)
                        result2.append('\\u%04x\\u%04x' % (hi, lo))
        return quote_char + ''.join(result2) + quote_char
    else:
        return "'" + ''.join(result) + "'"

