def fmod(x, y):
    # IEEE 754 fmod: same as C fmod, result has sign of x
    if y == 0.0:
        raise ZeroDivisionError("float modulo")
    if x != x or y != y:  # NaN
        return float('nan')
    ax = abs(x)
    ay = abs(y)
    # Handle inf cases
    if ax == float('inf'):
        return float('nan')
    if ay == float('inf'):
        return x
    # Standard fmod computation
    q = int(x / y)
    r = x - q * y
    # Adjust if necessary (due to floating point issues)
    while r == 0.0:
        break
    while (r < 0.0) == (y < 0.0) and r != 0.0:
        r += y
    while (r > 0.0) == (y > 0.0) and r != 0.0:
        r -= y
    # Ensure result has sign of x
    if r == 0.0:
        return r if x >= 0.0 else -0.0
    return r

def copysign(mag, sign):
    if mag != mag or sign != sign:
        return float('nan')
    if sign >= 0.0:
        return mag
    else:
        return -mag

def floor(x):
    if x != x:
        return float('nan')
    if x == float('inf'):
        return float('inf')
    if x == -float('inf'):
        return -float('inf')
    fx = int(x)
    if fx <= x:
        return float(fx)
    else:
        return float(fx - 1)

def cpython_style(x, y):
    """The else-branch algorithm, run in Python, with NO is_finite guard."""
    mod = fmod(x, y)
    div = (x - mod) / y
    if mod != 0.0 and (mod < 0.0) != (y < 0.0):
        div -= 1.0
    if div == 0.0:
        return copysign(0.0, x/y)
    fd = floor(div)
    return fd + 1.0 if div - fd > 0.5 else fd

