    # IEEE 754 fmod: result has same sign as x, magnitude < |y|
    if y == 0.0:
        raise ZeroDivisionError("fmod by zero")
    if x != x or y != y:
        return float('nan')
    # Use Python's % which gives remainder with sign of divisor
    r = x % y
    # Python % result has sign of y; fmod has sign of x
    if r != 0.0 and (r < 0.0) != (x < 0.0):
        r += y
    return r

def _copysign(a, b):
    if a == 0.0:
        if str(b).startswith('-') or (b < 0.0):
            return -0.0
        else:
            return 0.0
    if b < 0.0:
        return -abs(a)
    else:
        return abs(a)

def _floor(x):
    import sys
    if x != x:
        return float('nan')
    if x == float('inf'):
        return float('inf')
    if x == float('-inf'):
        return float('-inf')
    if x >= 0.0:
        return float(int(x))
    else:
        # For negative numbers, floor is the greatest integer <= x
        n = int(x)
        if float(n) < x:
            n += 1
        return float(n)

def cpython_style(x, y):
    """The else-branch algorithm, run in Python, with NO is_finite guard."""
    mod = _fmod(x, y)
    div = (x - mod) / y
    if mod != 0.0 and (mod < 0.0) != (y < 0.0):
        div -= 1.0
    if div == 0.0:
        return _copysign(0.0, x/y)
    fd = _floor(div)
    return fd + 1.0 if div - fd > 0.5 else fd

