import os, sys

def _fmod(x, y):
    """Emulate math.fmod for floats: fmod(x,y) = x - trunc(x/y)*y, with IEEE semantics."""
    if y == 0.0:
        # fmod by zero raises ValueError in CPython
        raise ValueError("math domain error")
    # Handle inf/nan cases matching CPython fmod
    if x != x or y != y:  # nan
        return float('nan')
    if x == float('inf') or x == float('-inf') or y == float('inf') or y == float('-inf'):
        return float('nan')
    q = int(x / y)  # truncation toward zero
    r = x - q * y
    # Ensure sign of result matches sign of x
    if r != 0.0 and (r < 0.0) != (x < 0.0):
        r += y if (x < 0.0) else -y
    # If r is zero, preserve sign of x
    if r == 0.0:
        return 0.0 if x >= 0.0 else -0.0
    return r

def _floor(x):
    """Emulate math.floor for floats."""
    if x != x:  # nan
        raise ValueError("cannot convert float NaN to integer")
    if x == float('inf'):
        raise OverflowError("cannot convert float infinity to integer")
    if x == float('-inf'):
        raise OverflowError("cannot convert float infinity to integer")
    i = int(x)
    if float(i) != x:
        if x > 0:
            return i if i > x else i
        else:
            return i if i < x else i - 1 if i != x else i
    return i

def _floor_val(x):
    """Return floor as a float."""
    return float(_floor(x))

def _copysign(mag, sign):
    """Emulate math.copysign(mag, sign)."""
    if mag != mag:
        return float('nan')
    if sign == 0.0:
        # Check sign bit of sign
        import struct
        s = struct.unpack('d', struct.pack('d', sign))[0]
        # Determine if -0.0
        # Use a trick: 1/sign gives +/- inf
        try:
            inv = 1.0 / sign
            neg = (inv < 0)
        except:
            neg = False
    else:
        neg = (sign < 0.0)
    m = abs(mag)
    return -m if neg else m

