    # r = x - sign(x) * floor(abs(x)/abs(y)) * abs(y) ... no that's not quite right either.

    # The correct formula: fmod(x,y) = x - trunc(x/y)*y
    # where trunc(n) is n rounded toward zero.

    # For floating point, we can do:
    if x == 0:
        return 0.0 if y > 0 else -0.0

    abs_x = abs(x)
    abs_y = abs(y)

