import random, time, os

def E(p, tags=()):
    self = {}
    self['program'] = p
    self['tags'] = tags
    return self

def is_seeded_stream(e):
    p = e['program']
    lines = [l.strip() for l in p.split('\n')]
    for line in lines:
        if '#' in line:
            line = line.split('#')[0].strip()
        if "random.seed" in line and not line.startswith("print"):
            if "random.seed(1)" in line or "random.seed(5)" in line or "random.seed(None or 5)" in line:
                return True
            if "getattr(random, 'seed')(1)" in line:
                return True
            if "s = random.seed" in line:
                return True
    return False

def is_run_specific(e):
    p = e['program']
    lines = [l.strip() for l in p.split('\n')]
    for line in lines:
        if '#' in line:
            line = line.split('#')[0].strip()
        if "random.seed" in line and not line.startswith("print"):
            if "time.time()" in line or "os.getpid()" in line:
                return True
    return False

def is_nondeterministic(e):
    return not is_seeded_stream(e)

