import os

def isnan(v):
    return v != v

def isinf(v):
    return v == float('inf') or v == float('-inf')

def fmod(x, y):
    if isnan(x) or isnan(y) or isinf(y):
        return float('nan')
    if isinf(x):
        return float('nan')
    if y == 0.0:
        return float('nan')
    # Compute fmod using integer division approach
    # fmod(x,y) = x - trunc(x/y)*y
    q = x / y
    if isinf(q):
        return x
    # Truncate towards zero
    if q >= 0:
        t = int(q)
    else:
