def safe_eval(expr):
    """Evaluate the known re.* expressions without using eval."""

    # We need to parse these specific forms:
    # re.sub(pattern, repl, string)
    # re.sub(pattern, repl, string, count)
    # re.subn(pattern, repl, string, count)
    # re.split(pattern, string, maxsplit)

    # Let's handle each case by parsing the arguments

    expr = expr.strip()

    if expr.startswith("re.sub(") and expr.endswith(")"):
        inner = expr[7:-1]  # strip "re.sub(" and ")"
        args = split_args(inner)
        if len(args) == 3:
            pattern, repl, string = parse_arg(args[0]), parse_arg(args[1]), parse_arg(args[2])
            return re.sub(pattern, repl, string)
        elif len(args) == 4:
            pattern, repl, string, count = (parse_arg(a) for a in args)
            return re.sub(pattern, repl, string, count)

    elif expr.startswith("re.subn(") and expr.endswith(")"):
        inner = expr[8:-1]
        args = split_args(inner)
        if len(args) == 4:
            pattern, repl, string, count = (parse_arg(a) for a in args)
            return re.subn(pattern, repl, string, count)

    elif expr.startswith("re.split(") and expr.endswith(")"):
        inner = expr[9:-1]
        args = split_args(inner)
        if len(args) == 3:
            pattern, string, maxsplit = parse_arg(args[0]), parse_arg(args[1]), parse_arg(args[2])
            return re.split(pattern, string, maxsplit)

    raise ValueError("Cannot evaluate: " + expr)

def split_args(s):
    """Split top-level comma-separated arguments, respecting quotes and brackets."""
    args = []
    depth = 0
    in_string = False
    string_char = None
    i = 0
    current = []

    while i < len(s):
        c = s[i]

        if in_string:
            current.append(c)
            if c == '\\' and i + 1 < len(s):
                current.append(s[i+1])
                i += 2
                continue
            elif c == string_char:
                in_string = False
            i += 1
            continue

        if c in ("'", '"'):
            in_string = True
            string_char = c
            current.append(c)
            i += 1
            continue

        if c in '([{':
            depth += 1
        elif c in ')]}':
            depth -= 1

        if c == ',' and depth == 0:
            args.append(''.join(current).strip())
            current = []
        else:
            current.append(c)

        i += 1

    if current:
        args.append(''.join(current).strip())

    return args

def parse_arg(arg):
    """Parse a single argument from the expression."""
    arg = arg.strip()

    # Lambda function
    if arg.startswith("lambda"):
        # This is tricky - we need to handle lambda m: m.group(0).upper()
        # For now, let's use a special approach
        return _make_lambda(arg)

    # Raw string
    if arg.startswith("r'") and arg.endswith("'"):
        content = arg[2:-1]
        return _unescape_raw(content)
    elif arg.startswith('r"') and arg.endswith('"'):
        content = arg[2:-1]
        return _unescape_raw(content)

    # Regular string with single quotes
    if arg.startswith("'") and arg.endswith("'"):
        content = arg[1:-1]
        return _unescape_normal(content)
    elif arg.startswith('"') and arg.endswith('"'):
        content = arg[1:-1]
        return _unescape_normal(content)

    # Integer
    try:
        return int(arg)
    except ValueError:
        pass

    raise ValueError("Cannot parse arg: " + arg)

def _unescape_raw(content):
    """Unescape a raw string. In raw strings, backslashes are literal except before the quote."""
    # In a raw string, backslash-quote doesn't escape the quote for termination purposes
    # but in our case we've already split it out
    return content

def _unescape_normal(content):
    """Unescape a normal Python string literal."""
    result = []
    i = 0
    while i < len(content):
        c = content[i]
        if c == '\\' and i + 1 < len(content):
            nc = content[i+1]
            if nc == 'n':
                result.append('\n')
            elif nc == 't':
                result.append('\t')
            elif nc == 'r':
                result.append('\r')
            elif nc == '\\':
                result.append('\\')
            elif nc == "'":
                result.append("'")
            elif nc == '"':
                result.append('"')
            elif nc == '0':
                result.append('\0')
            elif nc == 'x':
                # hex escape
                hex_str = content[i+2:i+4]
                result.append(chr(int(hex_str, 16)))
                i += 4
                continue
            elif nc == 'u':
                hex_str = content[i+2:i+6]
                result.append(chr(int(hex_str, 16)))
                i += 6
                continue
            else:
                result.append('\\' + nc)
            i += 2
        else:
            result.append(c)
            i += 1
    return ''.join(result)

def _make_lambda(arg):
    """Create a lambda function from its source representation."""
    # The only lambda we need is: lambda m: m.group(0).upper()
    if arg == "lambda m: m.group(0).upper()":
        return lambda m: m.group(0).upper()
    raise ValueError("Cannot create lambda: " + arg)

