import ast

def safe_eval(expr):
    """Safely evaluate the specific expressions used in this program."""
    tree = ast.parse(expr, mode='eval')
    return _eval_node(tree.body)

def _eval_node(node):
    if isinstance(node, ast.Call):
        func = node.func
        if isinstance(func, ast.Attribute):
            if isinstance(func.value, ast.Name) and func.value.id == 're':
                fname = func.attr
                args = [_eval_node(a) for a in node.args]
                kwargs = {kw.arg: _eval_node(kw.value) for kw in node.keywords}
                if fname == 'sub':
                    return re.sub(*args, **kwargs)
                elif fname == 'subn':
                    return re.subn(*args, **kwargs)
                elif fname == 'split':
                    return re.split(*args, **kwargs)
                elif fname == 'escape':
                    return re.escape(*args, **kwargs)
        elif isinstance(func, ast.Name):
            if func.id == 'lambda':
                pass
    elif isinstance(node, ast.Constant):
        return node.value
    elif isinstance(node, ast.Str):
        return node.s
    elif isinstance(node, ast.Num):
        return node.n
    elif isinstance(node, ast.Name):
        if node.id == 'True':
            return True
        elif node.id == 'False':
            return False
        elif node.id == 'None':
            return None
        else:
            raise NameError(name=node.id + ' is not defined')
    elif isinstance(node, ast.Lambda):
        # Handle lambda for re.sub with function argument
        return _make_lambda(node)
    elif isinstance(node, ast.Attribute):
        # For m.group(0) etc. - but these are inside lambdas, handled differently
        raise NotImplementedError("Attribute access outside lambda not supported")
    elif isinstance(node, ast.BinOp):
        left = _eval_node(node.left)
        right = _eval_node(node.right)
        if isinstance(node.op, ast.Mult):
            return left * right
        elif isinstance(node.op, ast.Add):
            return left + right
        elif isinstance(node.op, ast.Sub):
            return left - right
        elif isinstance(node.op, ast.Div):
            return left / right
        elif isinstance(node.op, ast.FloorDiv):
            return left // right
        elif isinstance(node.op, ast.Mod):
            return left % right
        elif isinstance(node.op, ast.Pow):
            return left ** right
    elif isinstance(node, ast.UnaryOp):
        operand = _eval_node(node.operand)
        if isinstance(node.op, ast.USub):
            return -operand
        elif isinstance(node.op, ast.UAdd):
            return +operand
        elif isinstance(node.op, ast.Not):
            return not operand
        elif isinstance(node.op, ast.Invert):
            return ~operand
    elif isinstance(node, ast.Compare):
        left = _eval_node(node.left)
        for op, comparator in zip(node.ops, node.comparators):
            right = _eval_node(comparator)
            if isinstance(op, ast.Eq):
                if not (left == right):
                    return False
            elif isinstance(op, ast.NotEq):
                if not (left != right):
                    return False
            elif isinstance(op, ast.Lt):
                if not (left < right):
                    return False
            elif isinstance(op, ast.LtE):
                if not (left <= right):
                    return False
            elif isinstance(op, ast.Gt):
                if not (left > right):
                    return False
            elif isinstance(op, ast.GtE):
                if not (left >= right):
                    return False
            elif isinstance(op, ast.Is):
                if not (left is right):
                    return False
            elif isinstance(op, ast.IsNot):
                if not (left is not right):
                    return False
            left = right
        return True
    elif isinstance(node, ast.BoolOp):
        values = [_eval_node(v) for v in node.values]
        if isinstance(node.op, ast.And):
            result = True
            for v in values:
                result = v
                if not result:
                    break
            return result
        elif isinstance(node.op, ast.Or):
            result = False
            for v in values:
                result = v
                if result:
                    break
            return result
    elif isinstance(node, ast.List):
        return [_eval_node(e) for e in node.elts]
    elif isinstance(node, ast.Tuple):
        return tuple(_eval_node(e) for e in node.elts)
    elif isinstance(node, ast.Dict):
        return {_eval_node(k): _eval_node(v) for k, v in zip(node.keys, node.values)}
    elif isinstance(node, ast.IfExp):
        if _eval_node(node.test):
            return _eval_node(node.body)
        else:
            return _eval_node(node.orelse)
    else:
        raise NotImplementedError(type(node).__name__)

def _make_lambda(node):
    """Create a callable from an ast.Lambda node."""
    args = [a.arg for a in node.args.args]

    def make_func(args_list):
