    paren_pos = rest.find('(')
    if paren_pos == -1:
        raise ValueError("Expected function call")

    func_name = rest[:paren_pos]

    # Extract the arguments string (between first ( and last ))
    args_str = rest[paren_pos+1:-1]  # assuming ends with )

    # Now we need to split args_str into individual arguments, respecting quotes and nested parens/brackets
    args = []
    current = []
    depth = 0
    in_string = None
    i = 0
    while i < len(args_str):
        c = args_str[i]
        if in_string:
            if c == '\\':
                current.append(c)
                if i + 1 < len(args_str):
                    current.append(args_str[i+1])
                    i += 1
            elif c == in_string:
                in_string = None
                current.append(c)
            else:
                current.append(c)
        else:
            if c in ('"', "'"):
                in_string = c
                current.append(c)
            elif c in '([{':
                depth += 1
                current.append(c)
            elif c in ')]}':
                depth -= 1
                current.append(c)
            elif c == ',' and depth == 0:
                args.append(''.join(current))
                current = []
            else:
                current.append(c)
        i += 1
    if current:
        args.append(''.join(current))

    # Strip whitespace from each arg
    args = [a.strip() for a in args]

    # Now evaluate each argument
