def _unescape_string(s, is_bytes=False):
    """Unescape a Python string literal content."""
    result = []
    i = 0
    while i < len(s):
        c = s[i]
        if c == '\\' and i + 1 < len(s):
            nc = s[i+1]
            if nc == 'n':
                result.append('\n')
                i += 2
            elif nc == 't':
                result.append('\t')
                i += 2
            elif nc == 'r':
                result.append('\r')
                i += 2
            elif nc == '\\':
                result.append('\\')
                i += 2
            elif nc == "'":
                result.append("'")
                i += 2
            elif nc == '"':
                result.append('"')
                i += 2
            elif nc == 'x' and i + 3 < len(s):
                hexstr = s[i+2:i+4]
                result.append(chr(int(hexstr, 16)))
                i += 4
            elif nc == 'u' and i + 5 < len(s):
                hexstr = s[i+2:i+6]
                result.append(chr(int(hexstr, 16)))
                i += 6
            elif nc == 'U' and i + 9 < len(s):
                hexstr = s[i+2:i+10]
                result.append(chr(int(hexstr, 16)))
                i += 10
            else:
                result.append(c)
                result.append(nc)
                i += 2
        else:
            result.append(c)
            i += 1
    return ''.join(result)

