            nc = s[i+1]
            if nc == 'n':
                result.append(ord('\n'))
                i += 2
            elif nc == 't':
                result.append(ord('\t'))
                i += 2
            elif nc == 'r':
                result.append(ord('\r'))
                i += 2
            elif nc == '\\':
                result.append(ord('\\'))
                i += 2
            elif nc == "'":
                result.append(ord("'"))
                i += 2
            elif nc == '"':
                result.append(ord('"'))
                i += 2
            elif nc == 'x' and i + 3 < len(s):
                hexstr = s[i+2:i+4]
                result.append(int(hexstr, 16))
