def _split_args(s):
    # Split arguments on commas, respecting quotes and parens
    args = []
    depth = 0
    in_str = False
    str_char = ''
    i = 0
    start = 0
    while i < len(s):
        c = s[i]
        if in_str:
            if c == '\\':
                i += 2
                continue
            elif c == str_char:
                in_str = False
        else:
            if c in ("'", '"'):
                in_str = True
                str_char = c
            elif c == '(':
                depth += 1
            elif c == ')':
                depth -= 1
            elif c == ',' and depth == 0:
                args.append(s[start:i].strip())
                start = i + 1
        i += 1
    args.append(s[start:].strip())
    return args

