    if arg.startswith('r"') and arg.endswith('"'):
        return arg[2:-1]

    # b'...' or b"..." bytes
    if arg.startswith("b'") and arg.endswith("'"):
        return bytes(arg[2:-1], 'ascii')
    if arg.startswith('b"') and arg.endswith('"'):
        return bytes(arg[2:-1], 'ascii')

