def _decode_string(s, quote):
    # Decode escape sequences in a string
    result = []
    i = 0
    while i < len(s):
        if s[i] == '\\' and i + 1 < len(s):
            nxt = s[i+1]
            if nxt == 'n':
                result.append('\n')
                i += 2
            elif nxt == 't':
                result.append('\t')
                i += 2
            elif nxt == 'r':
                result.append('\r')
                i += 2
            elif nxt == '\\':
                result.append('\\')
                i += 2
            elif nxt == "'":
                result.append("'")
                i += 2
            elif nxt == '"':
                result.append('"')
                i += 2
            elif nxt == 'x':
                hex_str = s[i+2:i+4]
                result.append(chr(int(hex_str, 16)))
                i += 4
            elif nxt == 'u':
                hex_str = s[i+2:i+6]
                result.append(chr(int(hex_str, 16)))
                i += 6
            elif nxt == 'U':
                hex_str = s[i+2:i+10]
                result.append(chr(int(hex_str, 16)))
                i += 10
            else:
                result.append('\\' + nxt)
                i += 2
        else:
            result.append(s[i])
            i += 1
    return ''.join(result)

