import re
import ast

def _safe_eval(expr):
    """Evaluate a simple expression without using eval()."""
    tree = ast.parse(expr, mode='eval')
    return _eval_node(tree.body)

def _eval_node(node):
    if isinstance(node, ast.Constant):
        return node.value
    elif isinstance(node, ast.Name):
        return globals().get(node.id, _UNDEFINED)
    elif isinstance(node, ast.Call):
        func = _eval_node(node.func)
        args = [_eval_node(a) for a in node.args]
        kwargs = {kw.arg: _eval_node(kw.value) for kw in node.keywords}
        return func(*args, **kwargs)
    elif isinstance(node, ast.Attribute):
        value = _eval_node(node.value)
        return getattr(value, node.attr)
    else:
        raise NotImplementedError(f"Unsupported AST node: {type(node).__name__}")

