import binascii

def _b64encode(s, altchars=None):
    if isinstance(s, str):
        s = s.encode('utf-8')
    if isinstance(s, memoryview):
        s = bytes(s)
    if isinstance(s, bytearray):
        s = bytes(s)
    if not isinstance(s, (bytes, bytearray)):
        raise TypeError("expected bytes-like object, not %s" % type(s).__name__)
    # Use binascii.b2a_base64 which is part of standard library
    enc = binascii.b2a_base64(bytes(s)).rstrip(b'\n')
    if altchars is not None:
        if len(altchars) != 2:
            raise ValueError("altchars must be length 2")
        enc = enc.replace(b'+', altchars[0:1]).replace(b'/', altchars[1:2])
    return enc

def _b64decode(s, validate=False):
    if isinstance(s, str):
        s = s.encode('ascii')
    if isinstance(s, memoryview):
        s = bytes(s)
    if isinstance(s, bytearray):
        s = bytes(s)
    if not isinstance(s, (bytes, bytearray)):
        raise TypeError("expected bytes-like object, not %s" % type(s).__name__)

    # Strip whitespace (newlines, spaces, tabs) as per base64 module behavior
    # The CPython base64.b64decode strips all ASCII whitespace
    ws = b'\r\n\t '
    cleaned = bytes(c for c in s if c not in ws)

    if validate:
        # In validate mode, we need to check that the input (after stripping) is valid base64
        # Valid chars: A-Z, a-z, 0-9, +, /, =
        valid_chars = set(b'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=')
        for c in cleaned:
            if c not in valid_chars:
                raise binascii.Error("Non-base64 digit found")

    # Pad if necessary
    pad_len = (-len(cleaned)) % 4
    if pad_len > 0:
        cleaned = cleaned + b'=' * pad_len

    try:
        return binascii.a2b_base64(cleaned)
    except binascii.Error as e:
        raise

def _urlsafe_b64decode(s):
    if isinstance(s, str):
        s = s.encode('ascii')
    if isinstance(s, memoryview):
        s = bytes(s)
    if isinstance(s, bytearray):
        s = bytes(s)
    if not isinstance(s, (bytes, bytearray)):
        raise TypeError("expected bytes-like object, not %s" % type(s).__name__)

    # Replace - with + and _ with /
    converted = s.replace(b'-', b'+').replace(b'_', b'/')
    return _b64decode(converted)

