        for ch in s:
            if ch == '=':
                filtered.append(ch)
            elif urlsafe:
                if ch in URL_MAP:
                    filtered.append(ch)
                else:
                    raise ValueError("Invalid base64 character: %r" % ch)
            else:
                if ch in STD_MAP:
                    filtered.append(ch)
                else:
                    raise ValueError("Invalid base64 character: %r" % ch)
        s = ''.join(filtered)
    else:
        # Discard non-alphabet chars (except =)
        filtered = []
        for ch in s:
            if ch == '=':
                filtered.append(ch)
            elif urlsafe:
                if ch in URL_MAP:
                    filtered.append(ch)
            else:
                if ch in STD_MAP:
