    # Check padding: '=' should only be at end, and count must make len % 4 == 0 after considering
    # Actually, the number of '=' should be such that total length is multiple of 4.
    # Let's count trailing equals
    eq_count = 0
    for ch in reversed(s):
        if ch == '=':
            eq_count += 1
        else:
            break
    # All equals must be at the end
    if '=' in s[:-eq_count] if eq_count > 0 else False:
        # Check if there's a '=' not at the end
        last_non_eq = -1
        for i in range(len(s)-1, -1, -1):
            if s[i] != '=':
                last_non_eq = i
                break
        for i in range(last_non_eq + 1 if last_non_eq >= 0 else 0, len(s)):
            if s[i] != '=':
                raise ValueError("Incorrect padding")

    # Now decode
    # The data part is s without trailing '='
    data_part = s[:-eq_count] if eq_count > 0 else s
    # Length of data_part must be such that (len(data_part) + eq_count) % 4 == 0
    total_len = len(data_part) + eq_count
    if total_len % 4 != 0:
        raise ValueError("Incorrect padding")

    # Convert to bits
    vals = []
    for ch in data_part:
        if urlsafe:
            vals.append(URL_MAP[ch])
        else:
            vals.append(STD_MAP[ch])

    # Group into 4s
    out_bytes = []
    for i in range(0, len(vals), 4):
        group = vals[i:i+4]
        while len(group) < 4:
            group.append(0)
        # Combine into 24 bits
        n = (group[0] << 18) | (group[1] << 12) | (group[2] << 6) | group[3]
        b1 = (n >> 16) & 0xFF
        b2 = (n >> 8) & 0xFF
        b3 = n & 0xFF
        out_bytes.append(b1)
        out_bytes.append(b2)
        out_bytes.append(b3)

    out = bytes(out_bytes)
    # Apply padding: if eq_count == 1, remove last 1 byte; if eq_count == 2, remove last 2 bytes
    if eq_count == 1:
        out = out[:-1]
    elif eq_count == 2:
        out = out[:-2]

    return out

